int parse_csv_records(int record_count, int* field_sizes, char** csv_data, char** parsed_buffer) {
    if (record_count <= 0 || field_sizes == NULL || csv_data == NULL || parsed_buffer == NULL) {
        return -1; // 参数错误
    }

    // 计算所需内存大小
    size_t total_size = 0;
    for (int i = 0; i < record_count; i++) {
        if (field_sizes[i] <= 0) {
            return -2; // 字段大小无效
        }
        total_size += field_sizes[i] + 1; // +1 为每个字段添加结束符
    }

    // 分配内存
    *parsed_buffer = (char*)malloc(total_size);
    if (*parsed_buffer == NULL) {
        return -3; // 内存分配失败
    }

    // 解析CSV数据
    char* current_pos = *parsed_buffer;
    for (int i = 0; i < record_count; i++) {
        if (csv_data[i] == NULL) {
            // 如果输入数据为空，填充空字符串
            *current_pos = '\0';
            current_pos++;
        } else {
            // 复制字段数据，限制长度为field_sizes[i]
            int copy_len = (strlen(csv_data[i]) < field_sizes[i]) ? 
                           strlen(csv_data[i]) : field_sizes[i];
            strncpy(current_pos, csv_data[i], copy_len);
            current_pos[copy_len] = '\0'; // 确保字符串结束
            current_pos += copy_len + 1; // 移动到下一个字段位置
        }
    }

    return 0; // 成功
}
