    // Test with very large record count that could cause integer overflow
    int record_count = 1000000; // Large number
    int* field_sizes = malloc(record_count * sizeof(int));
    if (field_sizes == NULL) {
        printf("FAIL: Could not allocate field sizes array\n");
        return -1;
    }

    // Fill with large field sizes that could cause overflow when multiplied
    for (int i = 0; i < record_count; i++) {
        field_sizes[i] = 2000; // Large field size
    }

    char** csv_data = malloc(record_count * sizeof(char*));
    if (csv_data == NULL) {
        printf("FAIL: Could not allocate CSV data array\n");
        free(field_sizes);
        return -1;
    }

    for (int i = 0; i < record_count; i++) {
        csv_data[i] = malloc(field_sizes[i] + 1);
        if (csv_data[i] == NULL) {
            printf("FAIL: Could not allocate CSV data string\n");
            for (int j = 0; j <= i; j++) {
                free(csv_data[j]);
            }
            free(csv_data);
            free(field_sizes);
            return -1;
        }
        memset(csv_data[i], 'a', field_sizes[i]);
        csv_data[i][field_sizes[i]] = '\0';
    }

    char* parsed_buffer = NULL;
    int result = parse_csv_records(record_count, field_sizes, csv_data, &parsed_buffer);

    printf("Integer overflow test completed (result: %d)\n", result);

    // Clean up
    for (int i = 0; i < record_count; i++) {
        free(csv_data[i]);
    }
    free(csv_data);
    free(field_sizes);
    if (parsed_buffer != NULL) {
        free(parsed_buffer);
    }

    return 0;
}

int test_heap_buffer_overflow() {
    printf("Testing heap buffer overflow vulnerability...\n");

    int record_count = 2;
    int field_sizes[] = {100, 200}; // Deliberately small sizes
