    // Create CSV data that's larger than the expected field sizes
    csv_data[0] = malloc(150); // More than field_sizes[0]
    if (csv_data[0] == NULL) {
        printf("FAIL: Could not allocate first CSV data\n");
        return -1;
    }
    memset(csv_data[0], 'a', 149);
    csv_data[0][149] = '\0';

    csv_data[1] = malloc(250); // More than field_sizes[1]
    if (csv_data[1] == NULL) {
        printf("FAIL: Could not allocate second CSV data\n");
        free(csv_data[0]);
        return -1;
    }
    memset(csv_data[1], 'b', 249);
    csv_data[1][249] = '\0';

    char* parsed_buffer = NULL;
    int result = parse_csv_records(record_count, field_sizes, csv_data, &parsed_buffer);

    printf("Heap buffer overflow test completed (result: %d)\n", result);

    free(csv_data[0]);
    free(csv_data[1]);
    if (parsed_buffer != NULL) {
        free(parsed_buffer);
    }

    return 0;
}

int test_negative_values() {
    printf("Testing negative values that could cause underflow...\n");

    int record_count = -5; // Negative record count
    int field_sizes[] = {10, 20};
    char* csv_data[] = {"test1", "test2"};
    char* parsed_buffer = NULL;

